script.setup:
const s=ctx.state,gl=ctx.gl;s.canvas=new OffscreenCanvas(1,1);s.c=s.canvas.getContext('2d');s.texture=gl.createTexture();s.bitmaps=[];
s.image=async name=>{const b=await createImageBitmap(await(await fetch(ctx.assets[name])).blob());s.bitmaps.push(b);return b;};
s.json=async name=>await(await fetch(ctx.assets[name])).json();
s.show=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,`#version 300 es
precision highp float;in vec2 v_uv;out vec4 outColor;uniform sampler2D u_image;void main(){outColor=texture(u_image,vec2(v_uv.x,1.-v_uv.y));}`);
s.meta=await s.json('result.json');s.a=await s.image('render-0.png');s.images=await Promise.all(["render-0.png","render-1.png","render-2.png"].map(s.image));s.labels=["First frame", "Middle frame", "Last frame"];s.atlas=await s.image('frames.png');

script.render:
const s=ctx.state,gl=ctx.gl,u=ctx.uniforms,[w,h]=ctx.resolution,c=s.c,m=Math.min(w,h);
if(s.canvas.width!==w||s.canvas.height!==h){s.canvas.width=w;s.canvas.height=h;}c.fillStyle='#09131f';c.fillRect(0,0,w,h);
const size=m*.8,left=(w-size)/2,top=(h-size)/2;
const caption=(text)=>{c.fillStyle='#bccbd8';c.font=Math.max(12,m*.021)+'px sans-serif';c.textAlign='center';c.fillText(text,w/2,h/2+m*.46);};
const frame=u.u_play?Math.floor(ctx.time*8)%17:u.u_frame;{const ratio=Math.min(size/640,size/360),iw=640*ratio,ih=360*ratio;c.drawImage(s.atlas,(frame%3)*640,Math.floor(frame/3)*360,640,360,left+(size-iw)/2,top+(size-ih)/2,iw,ih);}caption('Frame '+(frame+1)+' / 17 · AI VAE reconstruction');gl.bindTexture(gl.TEXTURE_2D,s.texture);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,s.canvas);
gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);gl.useProgram(s.show);ctx.utils.bindTexture(s.show,'u_image',s.texture,0);ctx.utils.drawFullscreen(s.show);ctx.publish('frame',frame+1);ctx.publish('reconstruction MSE',s.meta.frames[frame].loss);ctx.publish('latent shape',s.meta.latentShape.join(' × '));
